using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Environment = "production",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { DarkMode = true, BetaAccess = false }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Check if a feature flag is enabled")]
    public static string CheckFeatureFlag(
        [Description("The name of the feature flag to check")] string flagName)
    {
        var flags = new Dictionary<string, bool>
        {
            ["DarkMode"] = true,
            ["BetaAccess"] = false,
            ["NewDashboard"] = true
        };

        if (flags.TryGetValue(flagName, out var enabled))
            return $"Feature '{flagName}' is {(enabled ? "enabled" : "disabled")}";

        return $"Feature '{flagName}' not found. Available: {string.Join(", ", flags.Keys)}";
    }

    [McpServerTool, Description("Get the configured timeout value in seconds for a service")]
    public static string GetTimeout(
        [Description("Service name to look up timeout for")] string serviceName)
    {
        var timeouts = new Dictionary<string, int>
        {
            ["api"] = 30,
            ["database"] = 10,
            ["cache"] = 5
        };

        if (timeouts.TryGetValue(serviceName, out var timeout))
            return $"{serviceName} timeout: {timeout}s";

        return $"No timeout configured for '{serviceName}'. Known services: {string.Join(", ", timeouts.Keys)}";
    }
}

